@ExtendWith(MockitoExtension.class)
class UserServiceTest {
    @Mock
    private UserRepository userRepo;

    @InjectMocks
    private UserService userService;

    @Test
    void testGetUser() {
        // Arrange
        when(userRepo.findById(1L))
            .thenReturn(new User("สมชาย"));

